CREATE TABLE IF NOT EXISTS institutional_evidence_fulfilment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES institutional_evidence_requests(id) ON DELETE CASCADE, asset_id uuid NOT NULL REFERENCES assets(id) ON DELETE CASCADE, evidence_id uuid REFERENCES asset_evidence(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'requested', submitted_by text, submitted_at timestamptz, verified_at timestamptz, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id));